window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[187]={"id":"187","numero":187,"titre":"Hypersensibilité, allergies cutanées","objectifs":[{"id":"187-1","rang":"A","rubrique":"Définition","titre":"Définition de l'urticaire","contenu":"<p>L'<span class=\"kw-def\">urticaire</span> est une <span class=\"kw-def\">dermatose inflammatoire</span> fréquente, due à l'<span class=\"kw-def\">activation des mastocytes</span> par des mécanismes <strong>immunologiques</strong> mais <strong>surtout non-immunologiques</strong> — le médiateur le plus souvent impliqué, quel que soit le mécanisme, est l'<span class=\"kw-def\">histamine</span>.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Urticaire superficielle</strong></td><td><span class=\"kw-def\">Œdème dermique</span> ; isolée dans <span class=\"kw-chiffre\">50 %</span> des cas</td></tr>\n          <tr><td><strong>Urticaire profonde / angio-œdème</strong></td><td><span class=\"kw-def\">Œdème dermo-hypodermique</span> ; isolée dans <span class=\"kw-chiffre\">10 %</span> des cas</td></tr>\n          <tr><td><strong>Association</strong> superficielle + profonde</td><td><span class=\"kw-chiffre\">40 %</span> des cas</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><span class=\"kw-clinique\">Évolution aiguë</span> le plus souvent — <span class=\"kw-chiffre\">15 %</span> de la population fait une <span class=\"kw-clinique\">poussée d'urticaire</span> au cours de sa vie.</li>\n        <li><span class=\"kw-clinique\">Évolution chronique</span> plus rare — poussées quotidiennes pendant <span class=\"kw-chiffre\">&gt; 6 semaines</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 186 — Hypersensibilité - allergie · 338 — Œdème de Quincke - <span class=\"kw-alerte\">anaphylaxie</span></em></p>","frequence":1},{"id":"187-2","rang":"B","rubrique":"Éléments physiopathologiques","titre":"Bases physiopathologiques de l'urticaire","contenu":"<p>L'urticaire résulte d'une <span class=\"kw-def\">vasodilatation</span> avec <span class=\"kw-def\">augmentation de la perméabilité capillaire</span>, secondaire à la libération par les <span class=\"kw-def\">mastocytes</span> de médiateurs dont le principal est l'<span class=\"kw-def\">histamine</span>.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Immunologiques</strong></td><td><span class=\"kw-def\">Hypersensibilité immédiate</span> médiée par les <span class=\"kw-bio\">IgE</span> (récepteurs <span class=\"kw-bio\">FcεRI</span> sur le mastocyte → sensibilisation préalable)<br>Auto-anticorps <span class=\"kw-bio\">IgG anti-FcεRI</span> fixant le complément</td></tr>\n          <tr><td><strong>Non-immunologiques</strong><br>(les plus fréquents)</td><td>Stimulation directe de récepteurs mastocytaires<br>Apport excessif ou libération exagérée d'<span class=\"kw-def\">histamine</span><br>Action sur le métabolisme de l'<span class=\"kw-def\">acide arachidonique</span> (<span class=\"kw-etio\">AINS</span>, <span class=\"kw-etio\">aspirine</span>, pénicillines, <span class=\"kw-ttt\">codéine</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>L'activation du mastocyte se fait en <strong>3 phases</strong> : <span class=\"kw-def\">dégranulation</span> (histamine → œdème), synthèse d'<span class=\"kw-def\">eicosanoïdes</span> (leucotriènes, prostaglandines), sécrétion de <span class=\"kw-def\">cytokines</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> <span class=\"kw-chiffre\">&lt; 10 %</span> des urticaires ont une cause médicamenteuse ; les infections virales sont une cause fréquente, surtout chez l'<span class=\"kw-clinique\">enfant</span>.</div>\n      <p><strong>Physiopathologie comparée des 3 entités de l'item</strong> (à connaître) :</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Urticaire</strong></td><td><span class=\"kw-def\">Hypersensibilité type I</span>, IgE-médiée ; dégranulation des <span class=\"kw-bio\">mastocytes</span> et <span class=\"kw-bio\">basophiles</span></td></tr>\n          <tr><td><strong>Eczéma de contact</strong></td><td><span class=\"kw-def\">Hypersensibilité retardée</span> à médiation cellulaire (type IV) ; présentation de l'allergène aux <span class=\"kw-def\">Th1</span> (<em>idem tuberculose</em>)</td></tr>\n          <tr><td><strong>Dermatite atopique</strong></td><td>Présentation de l'allergène aux <span class=\"kw-def\">Th2</span> puis dégranulation (<em>idem asthme</em>)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"187-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une urticaire superficielle et profonde","contenu":"<table >\n        <thead><tr><th></th><th>Urticaire superficielle</th><th>Urticaire profonde / angio-œdème</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Lésion</strong></td><td><span class=\"kw-clinique\">Papules œdémateuses</span> « ortiées », rosées/érythémateuses, <strong>bordure nette</strong>, parfois centre plus clair</td><td><span class=\"kw-clinique\">Œdème blanc-rosé</span> ferme, <strong>mal limité</strong></td></tr>\n          <tr><td><strong>Caractère</strong></td><td><span class=\"kw-clinique\">Prurigineuses</span>, <span class=\"kw-clinique\">fugaces</span> (min à h), <span class=\"kw-clinique\">migratrices</span></td><td><span class=\"kw-alerte\">Non prurigineux</span> ; sensation de tension/cuisson</td></tr>\n          <tr><td><strong>Topographie</strong></td><td>Pas de siège préférentiel ; confluence en plaques « carte de géographie »</td><td><span class=\"kw-clinique\">Paupières</span>, <span class=\"kw-clinique\">lèvres</span>, extrémités, OGE</td></tr>\n          <tr><td><strong>Évolution</strong></td><td>Quelques minutes à quelques heures</td><td>Régression <span class=\"kw-chiffre\">&lt; 72 h</span> sans séquelle</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Urgence.</strong> La localisation <span class=\"kw-alerte\">laryngo-pharyngée</span> de l'angio-œdème (<span class=\"kw-alerte\">œdème de Quincke</span>) conditionne le <span class=\"kw-alerte\">pronostic vital</span> (voir « Savoir reconnaître une <span class=\"kw-alerte\">anaphylaxie</span> »).</div>\n      <p><strong>Diagnostic</strong> facile sur les lésions typiques + caractère <span class=\"kw-clinique\">fugace</span> et <span class=\"kw-clinique\">migrateur</span>. En cas d'<strong>atypies</strong> (lésions <span class=\"kw-alerte\">fixes</span>, persistant plusieurs jours), évoquer les diagnostics différentiels :</p>\n      <ul>\n        <li><span class=\"kw-etio\">DBAI</span> au stade pré-bulleux</li>\n        <li><span class=\"kw-etio\">Érythème polymorphe</span></li>\n        <li><span class=\"kw-etio\">Vascularite urticarienne</span>, <span class=\"kw-etio\">maladie de Still</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 338 — Œdème de Quincke - <span class=\"kw-alerte\">anaphylaxie</span> · 112 — Dermatose bulleuse auto-immune</em></p>","frequence":1},{"id":"187-4","rang":"A","rubrique":"Contenu multimédia","titre":"Savoir reconnaître une urticaire","contenu":"<p><strong>Sémiologie visuelle attendue</strong> — <span class=\"kw-clinique\">papules</span> et <span class=\"kw-clinique\">plaques œdémateuses</span> « <span class=\"kw-clinique\">ortiées</span> », <span class=\"kw-clinique\">rosées</span> à <span class=\"kw-clinique\">érythémateuses</span>, à <span class=\"kw-clinique\">bordure nette</span>, confluant en larges plaques à <span class=\"kw-clinique\">contours géographiques</span>. Aspects possibles : lésions <span class=\"kw-clinique\">annulaires</span> ou <span class=\"kw-clinique\">polycycliques</span>, <span class=\"kw-clinique\">micropapuleuses</span>, <span class=\"kw-clinique\">bulleuses</span>. Caractère <span class=\"kw-clinique\">fugace</span> et <span class=\"kw-clinique\">migrateur</span> (durée <span class=\"kw-chiffre\">&lt; 24 h</span> pour une lésion donnée).</p>\n      <div class=\"callout callout-warn\"><strong>Photo à ajouter.</strong> Objectif « Contenu multimédia » : photo de plaques œdémateuses d'urticaire. Kevin déposera l'image dans <code>assets/images/187/</code>.</div>\n      <!-- TODO Kevin : déposer urticaire-plaques-oedemateuses.jpg dans assets/images/187/ -->","frequence":0},{"id":"187-5","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître une anaphylaxie","contenu":"<p>Dans une minorité de cas, l'urticaire et/ou l'angio-œdème s'associe à des manifestations d'<span class=\"kw-alerte\">anaphylaxie</span> — urgence vitale.</p>\n      <div class=\"callout callout-danger\"><strong>Œdème de Quincke.</strong> Localisation <span class=\"kw-alerte\">laryngo-pharyngée</span>, potentiellement <span class=\"kw-alerte\">létale par asphyxie</span> (gonflement de la langue, luette, lèvres, face).</div>\n      <p><strong>Signes d'alerte</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Dyspnée</span>, <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">dysphonie</span>, raucité de la voix</li>\n        <li><span class=\"kw-clinique\">Cornage</span>, <span class=\"kw-clinique\">stridor</span>, <span class=\"kw-clinique\">tirage</span></li>\n        <li>Manifestations systémiques <span class=\"kw-alerte\">&gt; grade 2</span> : <span class=\"kw-clinique\">bronchospasme</span>, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-alerte\">choc</span>, <span class=\"kw-clinique\">signes digestifs</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>CAT immédiate.</strong> <span class=\"kw-ttt\">Adrénaline IM</span> sans délai (voir « traitement de l'urticaire aiguë »).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 338 — Œdème de Quincke - <span class=\"kw-alerte\">anaphylaxie</span></em></p>","frequence":0},{"id":"187-6","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de l'urticaire","contenu":"<p>Cinq grandes familles étiologiques : <strong>physiques, de contact, alimentaires, médicamenteuses, infectieuses</strong>.</p>\n      <p><strong>1. Urticaires physiques / inductibles</strong> (provoquées par un stimulus, reproductibles) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Facteur déclenchant / test</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Dermographisme</span> (urticaire factice)</td><td><span class=\"kw-clinique\">Frottement</span> ; test à la pointe mousse</td></tr>\n          <tr><td><span class=\"kw-etio\">Urticaire cholinergique</span></td><td><span class=\"kw-clinique\">Effort</span>, sudation, douche chaude, émotions (papules <span class=\"kw-chiffre\">1-5 mm</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Urticaire au froid</span></td><td>Contact froid (air, eau, objets) ; <strong>test au glaçon</strong> ; <span class=\"kw-alerte\">réaction oropharyngée</span> possible</td></tr>\n          <tr><td><span class=\"kw-etio\">Urticaire solaire</span></td><td>Exposition solaire ; photo-tests</td></tr>\n          <tr><td><span class=\"kw-etio\">Urticaire retardée à la pression</span></td><td><span class=\"kw-chiffre\">4-8 h</span> après appui ; test <span class=\"kw-chiffre\">7 kg / 20 min</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>2. Alimentaires</strong> — <span class=\"kw-etio\">IgE-dépendantes</span> (rares) vs pseudo-allergie (aliments histamino-libérateurs : <span class=\"kw-etio\">fromages fermentés</span>, charcuteries, chocolat, fraises). Arguments en faveur d'une allergie : délai <span class=\"kw-chiffre\">&lt; 2 h</span>, gravité <span class=\"kw-chiffre\">&gt; grade 2</span>, résolution <span class=\"kw-chiffre\">&lt; 12 h</span>, <strong>récidive à chaque prise</strong>.</p>\n      <p><strong>3. Médicamenteuses</strong> — tous les médicaments (les plus fréquents : <span class=\"kw-etio\">ATB</span>, <span class=\"kw-etio\">AINS</span>, curares). IgE-dépendantes dans <span class=\"kw-chiffre\">&lt; 10 %</span> (ex. pénicilline) ; surtout non-immunologiques. Argument allergie : délai <span class=\"kw-chiffre\">&lt; 45 min</span>.</p>\n      <p><strong>4. De contact</strong> (latex, milieu professionnel) ; <strong>5. Infectieuses</strong> — virales (VAS de l'enfant ; <span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span>, hépatites = triade de Caroli : céphalée + arthralgie + urticaire ; parasitoses si <span class=\"kw-bio\">hyperéosinophilie</span>) ; <strong>piqûres d'hyménoptères</strong> (confirmation par <span class=\"kw-bio\">intradermoréactions</span> + IgE spécifiques au venin).</p>\n      <div class=\"callout callout-warn\"><strong>Angio-œdème bradykinique (<span class=\"kw-chiffre\">5 %</span>).</strong> Non mastocytaire — déficit en <span class=\"kw-bio\">inhibiteur de la C1-estérase (C1INH)</span> (héréditaire ou acquis : hémopathies lymphoïdes, paranéoplasique). Déclencheurs : <span class=\"kw-etio\">IEC</span>, <span class=\"kw-etio\">ARA2</span>, <span class=\"kw-etio\">gliptines</span>, œstroprogestatifs. Œdème mou, blanc, <strong>sans prurit ni urticaire</strong>, troubles digestifs. <span class=\"kw-alerte\">Ne répond NI aux anti-H1 NI aux corticoïdes</span> → traitement par <span class=\"kw-ttt\">icatibant</span> SC, <span class=\"kw-ttt\">concentré de C1INH</span> si crise grave.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 338 — Œdème de Quincke - <span class=\"kw-alerte\">anaphylaxie</span></em></p>","frequence":1},{"id":"187-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement d'une urticaire aiguë","contenu":"<div class=\"callout callout-info\"><strong>Dans tous les cas.</strong> <span class=\"kw-def\">Éviction du facteur déclenchant</span>.</div>\n      <table >\n        <thead><tr><th>Situation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Urticaire aiguë non grave</strong><br>(sans <span class=\"kw-clinique\">atteinte muqueuse</span>)</td><td><span class=\"kw-ttt\">Anti-H1 de 2ᵉ génération</span> per os (injectable si poussée intense), 1×/jour pendant <span class=\"kw-chiffre\">1 à 2 semaines</span></td></tr>\n          <tr><td><strong>Urticaire aiguë grave</strong><br>(<span class=\"kw-alerte\">angio-œdème laryngé</span> / <span class=\"kw-alerte\">anaphylaxie</span> <span class=\"kw-alerte\">&gt; grade 2</span>)</td><td><span class=\"kw-ttt\">Adrénaline IM</span> <span class=\"kw-chiffre\">0,01 mg/kg</span> (max <span class=\"kw-chiffre\">0,5 mg</span>, à répéter à <span class=\"kw-chiffre\">5-15 min</span>) ; voie IV titrée si <span class=\"kw-alerte\">choc</span>/ACR<br>Mesures associées : <span class=\"kw-chiffre\">O₂ 8-9 L/min</span>, remplissage, <span class=\"kw-ttt\">aérosol de β2-mimétiques</span> si <span class=\"kw-clinique\">asthme</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Urticaire chronique</strong> (complément) : <span class=\"kw-ttt\">anti-H1 de 2ᵉ génération</span> pendant <span class=\"kw-chiffre\">4-6 semaines</span> ; si persistance, augmentation jusqu'à <span class=\"kw-chiffre\">×4</span> la dose, ou <span class=\"kw-ttt\">omalizumab</span> (seule AMM dans l'urticaire chronique spontanée résistante aux anti-H1).</p>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> <span class=\"kw-ci\">Pas de corticothérapie générale</span> dans l'urticaire chronique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 338 — Œdème de Quincke - <span class=\"kw-alerte\">anaphylaxie</span></em></p>","frequence":2},{"id":"187-8","rang":"B","rubrique":"Éléments physiopathologiques","titre":"Connaître les facteurs responsables de l'atopie","contenu":"<div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-def\">dermatite atopique n'est PAS une allergie</span> (mais elle peut s'y associer). Trois familles de facteurs : <strong>génétiques, immunologiques, environnementaux</strong>.</div>\n      <table >\n        <thead><tr><th>Facteur</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Génétiques</strong></td><td><span class=\"kw-etio\">Atopie familiale</span> dans <span class=\"kw-chiffre\">&gt; 50 %</span> (prédisposition à produire des <span class=\"kw-bio\">IgE</span>) ; maladie polygénique<br><span class=\"kw-def\">Mutation perte de fonction de la filaggrine</span> chez ~<span class=\"kw-chiffre\">30 %</span> → ↑ perméabilité de la barrière, aggravée par la colonisation à <span class=\"kw-etio\">S. aureus</span></td></tr>\n          <tr><td><strong>Immunologiques</strong></td><td>Immunité innée : <span class=\"kw-bio\">↓ peptides antimicrobiens</span> → prédispose aux infections bactériennes/herpétiques<br>Immunité adaptative : <span class=\"kw-def\">différenciation Th2</span>, production d'<span class=\"kw-bio\">IgE</span> par les LB</td></tr>\n          <tr><td><strong>Environnementaux</strong></td><td>Irritants (<span class=\"kw-etio\">savons</span>, détergents, <span class=\"kw-etio\">tabac</span>) ; allergènes (<span class=\"kw-etio\">acariens</span>, aliments, animaux, pollen) ; <span class=\"kw-def\">théorie hygiéniste</span></td></tr>\n        </tbody>\n      </table>","frequence":3},{"id":"187-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les aspects cliniques de la dermatite atopique en fonction du stade et son mode évolutif","contenu":"<table >\n        <thead><tr><th>Stade</th><th>Aspect</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Phase aiguë (eczéma)</strong><br>très <span class=\"kw-clinique\">prurigineuse</span></td><td><strong>1.</strong> Érythémateuse (placard à <span class=\"kw-clinique\">contours émiettés</span>, <strong>mal limités</strong>)<br><strong>2.</strong> Vésiculeuse<br><strong>3.</strong> Suintante (érosion)<br><strong>4.</strong> Croûteuse/desquamative → guérison sans cicatrice en <span class=\"kw-chiffre\">7-15 j</span></td></tr>\n          <tr><td><strong>Phase chronique</strong></td><td>Lésions érythémato-<span class=\"kw-clinique\">squameuses</span> ; <span class=\"kw-clinique\">lichénification</span> (grattage chronique) ; kératodermie palmo-plantaire</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Localisations selon l'âge</strong> :</p>\n      <table >\n        <thead><tr><th>Âge</th><th>Topographie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Nourrisson</strong></td><td><span class=\"kw-clinique\">Zones convexes du visage</span> (respect médio-facial), membres, plis du cou, cuir chevelu (DD croûtes de lait) ; siège épargné</td></tr>\n          <tr><td><strong>Enfant &gt;<span class=\"kw-chiffre\"> 2 ans</span></strong></td><td><span class=\"kw-clinique\">Plis des coudes</span> et <span class=\"kw-clinique\">plis des genoux</span></td></tr>\n          <tr><td><strong>Adolescent / adulte</strong></td><td><span class=\"kw-clinique\">Visage</span> et <span class=\"kw-clinique\">cou</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li>Autres signes : <span class=\"kw-clinique\">prurit quasi-constant</span>, <span class=\"kw-clinique\">xérose</span>, dartres (macules hypopigmentées), <span class=\"kw-clinique\">signe de Dennie-Morgan</span> (double pli sous-palpébral), fissure sous-auriculaire.</li>\n        <li>Évolution <strong>par poussées</strong>, aggravation classique l'<span class=\"kw-clinique\">hiver</span> ; amélioration fréquente dans l'enfance (<span class=\"kw-chiffre\">3-5 %</span> évoluent vers une forme adulte).</li>\n      </ul>\n      <p><strong>Discriminant — contours des lésions</strong> :</p>\n      <table >\n        <thead><tr><th>Contours bien limités</th><th>Contours émiettés / mal limités</th></tr></thead>\n        <tbody>\n          <tr><td>Psoriasis ; Urticaire</td><td><strong>Dermatite atopique</strong> ; <strong>Eczéma de contact</strong> ; Lupus aigu ; Dermatite séborrhéique</td></tr>\n        </tbody>\n      </table>\n      <p><em>Critères de Williams (rang C) : prurit obligatoire + ≥ 3 critères parmi ATCD d'asthme/rhinite, début &lt;<span class=\"kw-chiffre\"> 2 ans</span>, atteinte des convexités, eczéma des plis, peau sèche.</em></p>","frequence":8},{"id":"187-10","rang":"A","rubrique":"Contenu multimédia","titre":"Savoir reconnaître une dermatite atopique","contenu":"<p><strong>Sémiologie visuelle attendue</strong> — chez le <span class=\"kw-clinique\">nourrisson en poussée</span> : placards <span class=\"kw-clinique\">érythémateux</span> <span class=\"kw-clinique\">mal limités</span> des <span class=\"kw-clinique\">zones convexes du visage</span> avec <span class=\"kw-clinique\">respect médio-facial</span>, lésions <span class=\"kw-clinique\">vésiculeuses</span> et <span class=\"kw-clinique\">suintantes</span>, parfois <span class=\"kw-clinique\">croûteuses</span> ; <span class=\"kw-clinique\">prurit</span> majeur (enfant qui se frotte et s'agite, <span class=\"kw-clinique\">insomnie</span>).</p>\n      <div class=\"callout callout-warn\"><strong>Photo à ajouter.</strong> Objectif « Contenu multimédia » : photo d'une dermatite atopique du nourrisson en poussée.</div>\n      <!-- TODO Kevin : déposer dermatite-atopique-nourrisson.jpg dans assets/images/187/ -->","frequence":0},{"id":"187-11","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications de la dermatite atopique","contenu":"<table >\n        <thead><tr><th>Complication</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Surinfection bactérienne</strong></td><td>Impétiginisation à <span class=\"kw-etio\">S. aureus</span> : <span class=\"kw-clinique\">pus</span>, croûtes jaunâtres, fièvre, ADP — à distinguer de la colonisation chronique</td></tr>\n          <tr><td><strong>Surinfection virale</strong></td><td><span class=\"kw-etio\">Molluscum contagiosum</span> (pox virus)<br><span class=\"kw-alerte\">Syndrome de Kaposi-Juliusberg</span> = eczema herpeticum</td></tr>\n          <tr><td><strong>Eczéma de contact</strong> surajouté</td><td>Sensibilisation aux topiques appliqués</td></tr>\n          <tr><td><strong>Ophtalmologique</strong></td><td><span class=\"kw-clinique\">Kératocône</span></td></tr>\n          <tr><td><strong>Croissance</strong></td><td>Retard dans les formes sévères (<strong>non</strong> dû aux dermocorticoïdes) → faire rechercher une <span class=\"kw-alerte\">allergie alimentaire</span></td></tr>\n          <tr><td><strong>Autres</strong></td><td><span class=\"kw-alerte\">Érythrodermie</span> ; altération majeure de la qualité de vie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Urgence — syndrome de Kaposi-Juliusberg.</strong> Complication d'une infection à <span class=\"kw-etio\">HSV1</span> chez un nourrisson <span class=\"kw-alerte\">atopique sévère &lt; 3 ans</span> : fièvre, <span class=\"kw-clinique\">vésicules hémorragiques</span> et <span class=\"kw-clinique\">pustules ombiliquées</span> en placard croûteux/nécrotique. <span class=\"kw-alerte\">Mortel sans traitement</span> → <span class=\"kw-ttt\">aciclovir IV</span> + <span class=\"kw-ci\">arrêt des dermocorticoïdes</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 114 — Exanthème - erythrodermie</em></p>","frequence":3},{"id":"187-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes du traitement de la dermatite atopique","contenu":"<table >\n        <thead><tr><th>Traitement</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Dermocorticoïdes</strong> (base)</td><td><span class=\"kw-ttt\">Dermocorticoïdes</span> : activité moyenne sur visage/plis/<span class=\"kw-chiffre\">&lt; 2 ans</span>, forte sur le corps/<span class=\"kw-chiffre\">&gt; 2 ans</span> ; <span class=\"kw-def\">règle de la phalangette</span> (<span class=\"kw-chiffre\">0,5 g</span> ≈ 2 paumes) ; 1×/j jusqu'à disparition de l'inflammation, sevrage progressif</td></tr>\n          <tr><td><strong>Émollients</strong></td><td><span class=\"kw-ttt\">Émollients</span> systématiques contre la <span class=\"kw-clinique\">xérose</span> (parfois mal tolérés en phase aiguë)</td></tr>\n          <tr><td><strong>Tacrolimus topique</strong></td><td><span class=\"kw-ttt\">Tacrolimus</span> (inhibiteur de la calcineurine) : visage/cou, formes modérées à sévères résistantes/CI aux dermocorticoïdes ; ordonnance d'exception</td></tr>\n          <tr><td><strong>Systémiques</strong> (formes sévères, adulte)</td><td>Photothérapie, <span class=\"kw-ttt\">ciclosporine</span>, <span class=\"kw-ttt\">dupilumab</span> (anti-IL4R), <span class=\"kw-ttt\">JAK inhibiteurs</span></td></tr>\n        </tbody>\n      </table>\n      <p>Mesures associées : toilette douce sans savon, éviction tabac/irritants, vaccination normale hors poussée (avis spécialisé si allergie à l'œuf pour grippe / fièvre jaune).</p>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> <span class=\"kw-ci\">Pas de corticothérapie générale</span> (risque de <span class=\"kw-alerte\">rebond</span>) ; homéopathie/phytothérapie non recommandées.</div>","frequence":6},{"id":"187-13","rang":"B","rubrique":"Éléments physiopathologiques","titre":"Physiopathologie de l'eczéma de contact","contenu":"<div class=\"callout callout-info\"><strong>Mécanisme.</strong> <span class=\"kw-def\">Hypersensibilité retardée à médiation cellulaire de type Th1</span> (type IV), en <strong>2 phases</strong>.</div>\n      <table >\n        <thead><tr><th>Phase</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Sensibilisation</strong><br>(asymptomatique, jours à années)</td><td>L'<span class=\"kw-def\">haptène</span> pénètre la peau et se couple à une protéine porteuse → capté par les <span class=\"kw-def\">cellules de Langerhans</span> qui migrent vers le ganglion → présentation aux <span class=\"kw-def\">LT naïfs</span> → <span class=\"kw-def\">LT mémoires</span> circulants</td></tr>\n          <tr><td><strong>Révélation</strong><br>(<span class=\"kw-chiffre\">24-48 h</span> après un nouveau contact)</td><td>Les <span class=\"kw-def\">LT mémoires</span> reconnaissent l'Ag → <span class=\"kw-bio\">cytokines pro-inflammatoires</span> (IL-2, IL-17, TNF, IFNγ) → recrutement de <span class=\"kw-bio\">cellules mononuclées</span> → <span class=\"kw-def\">spongiose</span> + <span class=\"kw-def\">exocytose</span> épidermiques</td></tr>\n        </tbody>\n      </table>\n      <p>Un <span class=\"kw-def\">haptène</span> est une molécule trop petite pour être immunogène seule : elle doit se coupler à une <strong>protéine porteuse</strong>. Histologie : <span class=\"kw-def\">spongiose</span> (<span class=\"kw-bio\">œdème intercellulaire</span> → <span class=\"kw-bio\">vésicules intra-épidermiques</span>), <span class=\"kw-def\">exocytose</span> (<span class=\"kw-bio\">afflux de LT</span>), infiltrat lymphocytaire <span class=\"kw-bio\">périvasculaire</span>.</p>","frequence":0},{"id":"187-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d'un eczéma aigu","contenu":"<p><strong>Phase aiguë</strong> très <span class=\"kw-clinique\">prurigineuse</span>, en 4 phases : <span class=\"kw-clinique\">érythémateuse</span> (<span class=\"kw-clinique\">contours émiettés</span>, mal limités) → <span class=\"kw-clinique\">vésiculeuse</span> → <span class=\"kw-clinique\">suintante</span> → <span class=\"kw-clinique\">croûteuse</span> (guérison <span class=\"kw-chiffre\">7-15 j</span>). <strong>Phase chronique</strong> : <span class=\"kw-clinique\">squames</span>, <span class=\"kw-clinique\">lichénification</span>, <span class=\"kw-clinique\">kératodermie palmo-plantaire</span>. Formes topographiques : aspect <span class=\"kw-clinique\">œdémateux</span> (paupières, OGE), <span class=\"kw-clinique\">zones photo-exposées</span>, <span class=\"kw-clinique\">eczéma dysidrosique</span> (paumes/plantes, <span class=\"kw-clinique\">vésicules dures</span>).</p>\n      <p><strong>Dermatite d'irritation vs eczéma de contact</strong> (discriminant majeur) :</p>\n      <table >\n        <thead><tr><th></th><th>Dermatite d'irritation</th><th>Eczéma de contact</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td>Agression physique/chimique directe, <strong>sans immunologie</strong></td><td><span class=\"kw-def\">HS retardée Th1</span></td></tr>\n          <tr><td><strong>Épidémiologie</strong></td><td>Majorité des sujets exposés</td><td>Quelques sujets exposés</td></tr>\n          <tr><td><strong>Délai</strong></td><td>Minutes à heures</td><td><span class=\"kw-chiffre\">24-48 h</span> après une nouvelle exposition</td></tr>\n          <tr><td><strong>Bords</strong></td><td><strong>Nets</strong></td><td><strong>Émiettés</strong></td></tr>\n          <tr><td><strong>Topographie</strong></td><td>Limitée à la zone de contact</td><td>Déborde de la zone de contact</td></tr>\n          <tr><td><strong>Symptôme</strong></td><td><span class=\"kw-clinique\">Brûlure</span></td><td><span class=\"kw-clinique\">Prurit</span></td></tr>\n          <tr><td><strong>Tests épicutanés</strong></td><td>Négatifs</td><td>Positifs</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 114 — Exanthème - erythrodermie</em></p>","frequence":0},{"id":"187-15","rang":"A","rubrique":"Contenu multimédia","titre":"Savoir reconnaître un eczéma aigu","contenu":"<p><strong>Sémiologie visuelle attendue</strong> — placard <span class=\"kw-clinique\">érythémateux</span> à <span class=\"kw-clinique\">contours émiettés</span> (<span class=\"kw-clinique\">mal limités</span>), parsemé de <span class=\"kw-clinique\">vésicules</span>, <span class=\"kw-clinique\">suintant</span>, très <span class=\"kw-clinique\">prurigineux</span>, <span class=\"kw-clinique\">débordant la zone de contact</span> avec l'<span class=\"kw-etio\">allergène</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Photo à ajouter.</strong> Objectif « Contenu multimédia » : photo d'un eczéma aigu.</div>\n      <!-- TODO Kevin : déposer eczema-aigu.jpg dans assets/images/187/ -->","frequence":0},{"id":"187-16","rang":"A","rubrique":"Étiologies","titre":"Connaître la démarche diagnostique étiologique dans un eczéma de contact et les principaux allergènes responsables","contenu":"<div class=\"callout callout-info\"><strong>Démarche.</strong> L'interrogatoire est central : la <span class=\"kw-def\">topographie initiale</span> de la lésion = zone de contact avec l'allergène (puis diffusion possible). Préciser circonstances des <span class=\"kw-chiffre\">24 h</span> à jours précédents, chronologie (amélioration week-ends/vacances), traitements locaux utilisés.</div>\n      <p>Allergène le plus fréquent = les <strong>métaux, surtout le <span class=\"kw-etio\">nickel</span></strong>.</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Allergène évoqué</th></tr></thead>\n        <tbody>\n          <tr><td>Lobule des oreilles, poignet, ombilic</td><td><span class=\"kw-etio\">Nickel</span> (bijoux, boutons, boucles)</td></tr>\n          <tr><td>Visage, paupières, cou</td><td><span class=\"kw-etio\">Cosmétiques</span>, vernis à ongles (manuporté), produits volatils (aéroporté)</td></tr>\n          <tr><td>Pieds</td><td><span class=\"kw-etio\">Chrome du cuir</span>, caoutchouc des chaussures</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Source</th><th>Allergènes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Professionnels</strong> (<span class=\"kw-alerte\">maladies professionnelles indemnisables</span>)</td><td><span class=\"kw-clinique\">Mains</span> ++, <span class=\"kw-clinique\">amélioration le week-end</span>. Métiers du bâtiment (<span class=\"kw-etio\">chrome du ciment</span>, <span class=\"kw-etio\">cobalt</span>, <span class=\"kw-etio\">résines époxy</span>), coiffeurs (<span class=\"kw-etio\">paraphénylènediamine</span>), professions de santé (<span class=\"kw-etio\">antiseptiques</span>, <span class=\"kw-etio\">caoutchouc des gants</span>), horticulteurs</td></tr>\n          <tr><td><strong>Médicaments topiques</strong></td><td><span class=\"kw-etio\">Néomycine</span>, <span class=\"kw-etio\">antiseptiques</span>, <span class=\"kw-etio\">sparadrap</span>, <span class=\"kw-etio\">baume du Pérou</span>, <span class=\"kw-etio\">AINS</span>. <span class=\"kw-alerte\">Allergie possible aux dermocorticoïdes</span> → à évoquer si une dermatose cortico-sensible s'aggrave</td></tr>\n          <tr><td><strong>Cosmétiques</strong></td><td><span class=\"kw-etio\">Parfums</span>, <span class=\"kw-etio\">méthylisothiazolinone</span>, <span class=\"kw-etio\">teintures (PPD)</span>, <span class=\"kw-etio\">vernis à ongles</span>, <span class=\"kw-etio\">déodorants</span></td></tr>\n          <tr><td><strong>Textiles / cuir / caoutchouc</strong></td><td><span class=\"kw-etio\">Colorants textiles</span>, <span class=\"kw-etio\">chrome du cuir</span>, <span class=\"kw-etio\">agents de vulcanisation</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Photo-allergènes</strong> : <span class=\"kw-etio\">photo-allergie</span> (lésions d'<span class=\"kw-clinique\">eczéma</span> <span class=\"kw-chiffre\">7-21 j</span> après le début du traitement) vs <span class=\"kw-etio\">photo-toxicité</span> (<span class=\"kw-clinique\">érythème actinique</span> dès les 1ᵉˢ prises).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 115 — Toxidermies</em></p>","frequence":3},{"id":"187-17","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le principe, la technique et l'interprétation des tests épicutanés","contenu":"<div class=\"callout callout-warn\"><strong>Ne pas confondre.</strong> <span class=\"kw-def\">Tests épicutanés</span> = patch-tests = épidermotests (explorent l'HS <strong>retardée</strong>, eczéma de contact) ≠ <span class=\"kw-def\">prick-tests</span> (HS <strong>immédiate</strong>, IgE).</div>\n      <ul>\n        <li><strong>Indications</strong> : toxidermies retardées, eczémas de contact. <span class=\"kw-ci\">Non recommandés</span> pour les allergies alimentaires retardées.</li>\n        <li><strong>Quand</strong> : à distance de la poussée (<span class=\"kw-chiffre\">1 mois</span>), en milieu spécialisé.</li>\n      </ul>\n      <p><strong>Technique</strong> : application des <span class=\"kw-etio\">allergènes</span> sous occlusion sur le <span class=\"kw-bio\">dos</span> pendant <span class=\"kw-chiffre\">24-48 h</span> (<span class=\"kw-bio\">pas d'effraction cutanée</span> ; témoin = <span class=\"kw-bio\">vaseline</span>). 1ʳᵉ lecture à <span class=\"kw-chiffre\">48 h</span>, 2ᵉ à <span class=\"kw-chiffre\">J3/J4</span> (parfois <span class=\"kw-chiffre\">J7</span> pour les <span class=\"kw-ttt\">corticoïdes</span>).</p>\n      <table >\n        <thead><tr><th>Cotation</th><th>Aspect</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>+</strong></td><td><span class=\"kw-clinique\">Érythème</span> + <span class=\"kw-clinique\">papule</span></td><td>Souvent irritatif</td></tr>\n          <tr><td><strong>++</strong></td><td>+ <span class=\"kw-clinique\">vésicules</span></td><td>Souvent allergique</td></tr>\n          <tr><td><strong>+++</strong></td><td><span class=\"kw-clinique\">Vésiculo-bulles</span></td><td>Presque toujours allergique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Limite.</strong> Un résultat <span class=\"kw-alerte\">négatif n'élimine pas</span> formellement une allergie de contact. <span class=\"kw-ci\">CI</span> : toxidermies graves, <span class=\"kw-ttt\">corticoïdes</span>/immunosuppresseurs (bloquent les LT).</div>","frequence":3,"liens":[{"href":"https://www.sfdermato.org/upload/groupe/bloc/file/batterie-standard-europeenne-2023.pdf","label":"Collège : Batterie standard européenne des patch-tests (SFD, 2023)"}]},{"id":"187-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes du traitement d'un eczéma de contact","contenu":"<div class=\"callout callout-info\"><strong>Indispensable.</strong> <span class=\"kw-def\">Éviction de l'allergène</span> — condition de la guérison : <span class=\"kw-alerte\">pas de désensibilisation possible</span> dans l'eczéma de contact.</div>\n      <table >\n        <thead><tr><th>Volet</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Symptomatique</strong></td><td><span class=\"kw-ttt\">Dermocorticoïdes</span> d'activité <span class=\"kw-chiffre\">forte à très forte</span>, 1×/j pendant <span class=\"kw-chiffre\">1-2 semaines</span><br><span class=\"kw-ttt\">Anti-H1 de 1ʳᵉ génération</span> quelques jours si <span class=\"kw-clinique\">prurit important</span> (les anti-H1 non sédatifs sont inutiles)</td></tr>\n          <tr><td><strong>Si surinfection</strong></td><td>ATB anti-<span class=\"kw-bio\">Gram+</span> : <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span>, sans retarder les dermocorticoïdes topiques</td></tr>\n        </tbody>\n      </table>\n      <p>Pour l'<span class=\"kw-etio\">eczéma professionnel</span> : collaboration avec le <span class=\"kw-alerte\">médecin du travail</span>, adaptation du poste, <span class=\"kw-alerte\">déclaration de maladie professionnelle</span>.</p>","frequence":2}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.sfdermato.org/upload/groupe/bloc/file/batterie-standard-europeenne-2023.pdf","label":"sfdermato.org"}],"cards":[{"i":"1d88c33c710e","n":187,"o":"187-1","u":"Définition","t":"Définition de l'urticaire","q":"Quels sont les différents modes d'évolution de l'urticaire ?","a":"<ul><li>Une évolution <strong>aiguë</strong> est la plus fréquente, touchant <strong>15% de la population</strong> au cours de sa vie.</li><li>Une évolution <strong>chronique</strong> est plus rare, définie par des poussées quotidiennes pendant <strong>plus de 6 semaines</strong>.</li></ul>"},{"i":"9b42fa6071dd","n":187,"o":"187-1","u":"Définition","t":"Définition de l'urticaire","q":"Quelle est la définition de l'urticaire ?","a":"<p>L'urticaire est une <strong>dermatose inflammatoire</strong> fréquente, caractérisée par l'activation des <strong>mastocytes</strong>, principalement par des mécanismes non immunologiques, et impliquant l'<strong>histamine</strong> comme médiateur principal.</p>"},{"i":"ecca8ab8d7a7","n":187,"o":"187-1","u":"Définition","t":"Définition de l'urticaire","q":"Quelles sont les différentes formes cliniques de l'urticaire et leurs caractéristiques ?","a":"<ul><li><strong>Urticaire superficielle</strong> : œdème limité au derme.</li><li><strong>Urticaire profonde</strong> ou <strong>angio-œdème</strong> : œdème qui s'étend au derme et à l'hypoderme.</li><li>Les deux formes peuvent être associées.</li></ul>"},{"i":"000f6f3619c3","n":187,"o":"187-10","u":"Contenu multimédia","t":"Savoir reconnaître une dermatite atopique","q":"Quel est le symptôme fonctionnel majeur d'une dermatite atopique en poussée chez le nourrisson et quelles en sont les conséquences ?","a":"<p>Le symptôme fonctionnel majeur est un <strong>prurit intense</strong> qui se manifeste par un enfant qui se frotte et s'agite, entraînant une <strong>insomnie</strong> notable.</p>"},{"i":"025bf291508d","n":187,"o":"187-10","u":"Contenu multimédia","t":"Savoir reconnaître une dermatite atopique","q":"Comment se manifeste une dermatite atopique en poussée chez le nourrisson sur le plan cutané ?","a":"<p>Chez le nourrisson en poussée, la dermatite atopique se caractérise par :</p><ul><li>Des <strong>placards érythémateux mal limités</strong>, situés sur les <strong>zones convexes du visage</strong>, avec un <strong>respect médio-facial</strong>.</li><li>Des <strong>lésions vésiculeuses et suintantes</strong>, parfois croûteuses.</li></ul>"},{"i":"24e56cccb02e","n":187,"o":"187-12","u":"Prise en charge","t":"Connaître les grands principes du traitement de la dermatite atopique","q":"Quels sont les pièges et les traitements non recommandés dans la prise en charge de la dermatite atopique ?","a":"<p>Il faut éviter la <strong>corticothérapie générale</strong>, qui présente un risque de <strong>rebond</strong>. L'<strong>homéopathie et la phytothérapie ne sont pas recommandées</strong> faute de preuves d'efficacité.</p>"},{"i":"8e5de43cf256","n":187,"o":"187-12","u":"Prise en charge","t":"Connaître les grands principes du traitement de la dermatite atopique","q":"Quelles sont les mesures associées et les traitements systémiques envisagés pour les formes sévères de dermatite atopique chez l'adulte ?","a":"<p>Les <strong>mesures associées</strong> comprennent :</p><ul><li>une <strong>toilette douce sans savon</strong>.</li><li>l'<strong>éviction du tabac et des irritants</strong>.</li><li>une <strong>vaccination normale hors poussée</strong> (avis spécialisé en cas d'allergie à l'œuf pour les vaccins contre la grippe ou la fièvre jaune).</li></ul><p>Pour les <strong>formes sévères chez l'adulte</strong>, les traitements systémiques possibles sont la <strong>photothérapie</strong>, la <strong>ciclosporine</strong>, le <strong>dupilumab</strong> (anti-IL4R) et les <strong>inhibiteurs de JAK</strong>.</p>"},{"i":"f23ae1b46584","n":187,"o":"187-12","u":"Prise en charge","t":"Connaître les grands principes du traitement de la dermatite atopique","q":"Quand et comment utilise-t-on le tacrolimus topique dans le traitement de la dermatite atopique ?","a":"<p>Le <strong>tacrolimus topique</strong> (inhibiteur de la calcineurine) est utilisé dans la dermatite atopique pour les <strong>formes modérées à sévères</strong>, particulièrement sur le <strong>visage et le cou</strong>, en cas de <strong>résistance ou de contre-indication aux dermocorticoïdes</strong>. Il est soumis à une <strong>ordonnance d'exception</strong>.</p>"},{"i":"ff69cd4e0036","n":187,"o":"187-12","u":"Prise en charge","t":"Connaître les grands principes du traitement de la dermatite atopique","q":"Quel est le traitement de première intention (base) de la dermatite atopique et comment l'utilise-t-on ?","a":"<p>Le traitement de première intention de la dermatite atopique repose sur les <strong>dermocorticoïdes</strong>. Leur activité est :</p><ul><li><strong>moyenne</strong> sur le visage, les plis et chez l'enfant de moins de 2 ans.</li><li><strong>forte</strong> sur le corps et chez l'enfant de plus de 2 ans.</li></ul><p>La posologie est d'<strong>une application par jour</strong> jusqu'à disparition de l'inflammation, suivie d'un <strong>sevrage progressif</strong>. La <strong>règle de la phalangette</strong> permet d'estimer les quantités : <strong>0,5 g équivaut à la surface de deux paumes</strong>.</p>"},{"i":"7c8894de3210","n":187,"o":"187-14","u":"Diagnostic positif","t":"Connaître les signes cliniques d'un eczéma aigu","q":"Comment se manifeste un eczéma aigu sur le plan clinique ?","a":"<p>Un eczéma aigu se manifeste par une phase <strong>très prurigineuse</strong> et évolue classiquement en <strong>4 phases successives</strong> :</p><ul><li>Phase <strong>érythémateuse</strong> : érythème à contours émiettés et mal limités.</li><li>Phase <strong>vésiculeuse</strong> : apparition de petites vésicules.</li><li>Phase <strong>suintante</strong> : rupture des vésicules et suintement.</li><li>Phase <strong>croûteuse</strong> : formation de croûtes, menant à la guérison en <strong>7 à 15 jours</strong>.</li></ul>"},{"i":"a4fa57e3cb16","n":187,"o":"187-14","u":"Diagnostic positif","t":"Connaître les signes cliniques d'un eczéma aigu","q":"Quelle est la principale caractéristique clinique permettant de différencier une dermatite d'irritation d'un eczéma de contact aigu ?","a":"<p>Le <strong>prurit</strong> est le symptôme discriminant majeur. Dans la <strong>dermatite d'irritation</strong>, la sensation prédominante est la <strong>brûlure</strong>, tandis que l'<strong>eczéma de contact</strong> se caractérise principalement par un <strong>prurit intense</strong>.</p>"},{"i":"dea5e8a5fb02","n":187,"o":"187-14","u":"Diagnostic positif","t":"Connaître les signes cliniques d'un eczéma aigu","q":"Quelles sont les formes topographiques particulières que peut prendre un eczéma aigu ?","a":"<p>L'eczéma aigu peut prendre des aspects particuliers selon sa localisation :</p><ul><li>Un aspect <strong>œdémateux</strong> peut être observé sur les paupières ou les organes génitaux externes (OGE).</li><li>Il peut affecter les <strong>zones photo-exposées</strong>.</li><li>L'<strong>eczéma dysidrosique</strong> est une forme particulière touchant les paumes et les plantes, caractérisée par des <strong>vésicules dures</strong>.</li></ul>"},{"i":"2f2d96777a5f","n":187,"o":"187-15","u":"Contenu multimédia","t":"Savoir reconnaître un eczéma aigu","q":"Comment reconnaître un eczéma aigu sur le plan sémiologique visuel ?","a":"<p>L'eczéma aigu se caractérise visuellement par :</p><ul><li>Un <strong>placard érythémateux</strong>.</li><li>Des <strong>contours émiettés</strong> (mal limités).</li><li>Il est <strong>parsemé de vésicules</strong>.</li><li>Il est <strong>suintant</strong>.</li><li>C'est une lésion <strong>très prurigineuse</strong>.</li><li>Il <strong>déborde la zone de contact</strong> avec l'allergène.</li></ul>"},{"i":"540d66306699","n":187,"o":"187-15","u":"Contenu multimédia","t":"Savoir reconnaître un eczéma aigu","q":"Quels sont les caractères des contours d'un placard d'eczéma aigu ?","a":"<p>Les contours d'un placard d'eczéma aigu sont typiquement <strong>émiettés</strong>, c'est-à-dire <strong>mal limités</strong>.</p>"},{"i":"f5c3a846ddd2","n":187,"o":"187-15","u":"Contenu multimédia","t":"Savoir reconnaître un eczéma aigu","q":"Quelle sensation cutanée est associée à l'eczéma aigu et quelle est sa particularité par rapport à la zone de contact ?","a":"<p>L'eczéma aigu est caractérisé par un <strong>prurit intense</strong> (très prurigineux). Il a la particularité de <strong>déborder la zone de contact</strong> initiale avec l'allergène.</p>"},{"i":"2a6e05f26b39","n":187,"o":"187-16","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique dans un eczéma de contact et les principaux allergènes responsables","q":"Quels types de produits médicamenteux topiques, cosmétiques et textiles peuvent être des allergènes de contact ?","a":"<ul><li><strong>Médicaments topiques</strong> : <strong>néomycine</strong>, <strong>antiseptiques</strong>, sparadrap, baume du Pérou, <strong>AINS</strong> (anti-inflammatoires non stéroïdiens). Une allergie aux <strong>dermocorticoïdes</strong> est possible si une dermatose habituellement corticosensible s'aggrave.</li><li><strong>Cosmétiques</strong> : <strong>parfums</strong>, <strong>méthylisothiazolinone</strong>, teintures (PPD), vernis à ongles, déodorants.</li><li><strong>Textiles / cuir / caoutchouc</strong> : <strong>colorants textiles</strong>, <strong>chrome du cuir</strong>, agents de vulcanisation.</li></ul>"},{"i":"433cf760e1e6","n":187,"o":"187-16","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique dans un eczéma de contact et les principaux allergènes responsables","q":"Quelle est l'approche diagnostique initiale devant un eczéma de contact pour identifier l'allergène ?","a":"<p>L'<strong>interrogatoire</strong> est central. Il faut rechercher :</p><ul><li>La <strong>topographie initiale</strong> de la lésion, qui oriente vers la zone de contact avec l'allergène.</li><li>Les <strong>circonstances</strong> des 24 heures à quelques jours précédant l'apparition des lésions.</li><li>La <strong>chronologie</strong>, notamment une éventuelle amélioration les week-ends ou pendant les vacances.</li><li>Les <strong>traitements locaux</strong> utilisés.</li></ul>"},{"i":"59dd5499a848","n":187,"o":"187-16","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique dans un eczéma de contact et les principaux allergènes responsables","q":"Quels sont les principaux allergènes de contact à considérer en fonction de la localisation des lésions sur le corps ?","a":"<ul><li><strong>Visage, paupières, cou</strong> : <strong>cosmétiques</strong>, <strong>vernis à ongles</strong> (par contact manuporté), ou produits volatils (aéroportés).</li><li><strong>Pieds</strong> : <strong>chrome du cuir</strong> ou <strong>caoutchouc des chaussures</strong>.</li><li><strong>Mains</strong> : fréquemment liés à des <strong>allergènes professionnels</strong> (ex: chrome du ciment, cobalt, résines époxy pour le bâtiment ; paraphénylènediamine pour les coiffeurs ; antiseptiques, caoutchouc des gants pour les professionnels de santé ; certains pesticides pour les horticulteurs).</li></ul>"},{"i":"9d34af71fd64","n":187,"o":"187-16","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique dans un eczéma de contact et les principaux allergènes responsables","q":"Quel est l'allergène le plus fréquemment impliqué dans l'eczéma de contact, et à quelle localisation faut-il y penser ?","a":"<p>L'allergène le plus fréquent est le <strong>nickel</strong>. Il doit être évoqué pour des lésions au niveau du <strong>lobule des oreilles</strong>, du <strong>poignet</strong> ou de l'<strong>ombilic</strong>, souvent liées aux bijoux, boutons ou boucles.</p>"},{"i":"2057203b8776","n":187,"o":"187-18","u":"Prise en charge","t":"Connaître les grands principes du traitement d'un eczéma de contact","q":"Comment doit être traitée une éventuelle surinfection bactérienne d'un eczéma de contact ?","a":"<p>En cas de surinfection, une antibiothérapie anti-Gram+ est indiquée, par exemple la <strong>pristinamycine</strong> ou l'<strong>amoxicilline-acide clavulanique</strong>. Il est important de ne pas retarder l'application des dermocorticoïdes topiques.</p>"},{"i":"ad2722159d43","n":187,"o":"187-18","u":"Prise en charge","t":"Connaître les grands principes du traitement d'un eczéma de contact","q":"Quelle est la base du traitement symptomatique de l'eczéma de contact ?","a":"<p>La base du traitement symptomatique repose sur les <strong>dermocorticoïdes</strong>. Ils doivent être d'activité <strong>forte à très forte</strong>, appliqués <strong>une fois par jour</strong> pendant <strong>1 à 2 semaines</strong>.</p>"},{"i":"ba0610aff3db","n":187,"o":"187-18","u":"Prise en charge","t":"Connaître les grands principes du traitement d'un eczéma de contact","q":"Quel est le principe fondamental du traitement de l'eczéma de contact ?","a":"<p>Le principe fondamental est l'<strong>éviction de l'allergène</strong>. C'est la condition indispensable à la guérison, car il n'existe pas de désensibilisation possible pour l'eczéma de contact.</p>"},{"i":"cc59c1db42f1","n":187,"o":"187-18","u":"Prise en charge","t":"Connaître les grands principes du traitement d'un eczéma de contact","q":"Quel est l'intérêt et le type d'antihistaminique à utiliser en cas de prurit important dans l'eczéma de contact ?","a":"<p>En cas de prurit important, des <strong>anti-histaminiques H1 de première génération</strong> peuvent être utilisés pendant quelques jours. Les anti-histaminiques non sédatifs sont inutiles.</p>"},{"i":"ec8a097e7b9c","n":187,"o":"187-18","u":"Prise en charge","t":"Connaître les grands principes du traitement d'un eczéma de contact","q":"Quelles sont les spécificités de la prise en charge d'un eczéma de contact professionnel ?","a":"<p>Pour un eczéma professionnel, une <strong>collaboration avec le médecin du travail</strong> est nécessaire. Elle implique une <strong>adaptation du poste</strong> de travail et une <strong>déclaration de maladie professionnelle</strong>.</p>"},{"i":"17d1e7b6398a","n":187,"o":"187-3","u":"Diagnostic positif","t":"Savoir diagnostiquer une urticaire superficielle et profonde","q":"Quelles sont les caractéristiques cliniques spécifiques des lésions d'urticaire superficielle qui orientent le diagnostic ?","a":"<p>Les lésions d'urticaire superficielle sont typiquement <strong>prurigineuses</strong>, <strong>fugaces</strong> (durée de quelques minutes à quelques heures), et <strong>migratrices</strong>.</p>"},{"i":"5a1cefcbcfbf","n":187,"o":"187-3","u":"Diagnostic positif","t":"Savoir diagnostiquer une urticaire superficielle et profonde","q":"Comment se présentent les lésions d'une urticaire superficielle symptomatique ?","a":"<p>Les lésions d'une urticaire superficielle sont des <strong>papules œdémateuses</strong>, dites « ortiées », de couleur <strong>rosée ou érythémateuse</strong>, avec une <strong>bordure nette</strong> et parfois un centre plus clair. Elles peuvent confluer en larges plaques à l'aspect « carte de géographie ».</p>"},{"i":"703cc9d01b85","n":187,"o":"187-3","u":"Diagnostic positif","t":"Savoir diagnostiquer une urticaire superficielle et profonde","q":"Comment se caractérisent les lésions d'une urticaire profonde, également appelée angio-œdème ?","a":"<p>L'urticaire profonde ou angio-œdème se manifeste par un <strong>œdème blanc-rosé ferme et mal limité</strong>. Il est souvent localisé aux <strong>paupières, lèvres, extrémités et organes génitaux externes (OGE)</strong>. Il n'est pas prurigineux mais plutôt responsable d'une <strong>sensation de tension ou de cuisson</strong>.</p>"},{"i":"bebcf60de7a0","n":187,"o":"187-3","u":"Diagnostic positif","t":"Savoir diagnostiquer une urticaire superficielle et profonde","q":"Quand faut-il évoquer des diagnostics différentiels face à des lésions urticariennes ?","a":"<p>Il faut évoquer des diagnostics différentiels en cas d'<strong>atypies</strong>, telles que des <strong>lésions fixes</strong> ou une <strong>persistance des lésions au-delà de quelques jours</strong>. Les diagnostics à considérer incluent les Dermatoses Bulleuses Auto-Immunes (DBAI) au stade pré-bulleux, l'érythème polymorphe, la vascularite urticarienne et la maladie de Still.</p>"},{"i":"c09185fcc38b","n":187,"o":"187-3","u":"Diagnostic positif","t":"Savoir diagnostiquer une urticaire superficielle et profonde","q":"Quel est le pronostic vital conditionné par l'angio-œdème et sa localisation ?","a":"<p>Le pronostic vital est conditionné par la localisation <strong>laryngo-pharyngée</strong> de l'angio-œdème, constituant un <strong>œdème de Quincke</strong>, qui peut entraîner une obstruction des voies aériennes supérieures.</p>"},{"i":"963e5d3384e9","n":187,"o":"187-4","u":"Contenu multimédia","t":"Savoir reconnaître une urticaire","q":"Comment évoluent les lésions d'urticaire sur la peau ?","a":"<p>Les lésions d'urticaire ont un caractère <strong>fugace et migrateur</strong>. Chaque lésion individuelle disparaît en <strong>moins de 24 heures</strong>, mais d'autres peuvent apparaître ailleurs.</p>"},{"i":"a03ab8e51232","n":187,"o":"187-4","u":"Contenu multimédia","t":"Savoir reconnaître une urticaire","q":"Quels sont les aspects morphologiques possibles et complémentaires que peuvent prendre les lésions d'urticaire ?","a":"<ul><li><strong>Lésions annulaires ou polycycliques</strong></li><li><strong>Lésions micropapuleuses</strong></li><li><strong>Lésions bulleuses</strong></li></ul>"},{"i":"fc9820959bc1","n":187,"o":"187-4","u":"Contenu multimédia","t":"Savoir reconnaître une urticaire","q":"Quelle est la caractéristique morphologique principale des lésions d'urticaire ?","a":"<p>Les lésions d'urticaire se présentent sous forme de <strong>papules et plaques œdémateuses</strong>, dites « ortiées », de couleur <strong>rosée à érythémateuse</strong>, avec une <strong>bordure nette</strong>.</p>"},{"i":"285f36505686","n":187,"o":"187-5","u":"Identifier une urgence","t":"Savoir reconnaître une anaphylaxie","q":"Quels sont les signes cliniques associés à un angio-œdème laryngo-pharyngé lors d'une anaphylaxie ?","a":"<p>Les signes cliniques d'un angio-œdème laryngo-pharyngé potentiellement létal par asphyxie comprennent :</p><ul><li>Gonflement de la langue, de la luette, des lèvres, et/ou de la face.</li><li>Dyspnée, dysphagie, dysphonie, raucité de la voix.</li><li>Cornage, stridor, tirage.</li></ul>"},{"i":"d62a799163a7","n":187,"o":"187-5","u":"Identifier une urgence","t":"Savoir reconnaître une anaphylaxie","q":"Quand suspecter une anaphylaxie associée à un angio-oedème ou une urticaire ?","a":"<p>L'anaphylaxie est à suspecter lorsque l'urticaire et/ou l'angio-œdème s'associent à des manifestations engageant le pronostic vital.</p>"},{"i":"e4157b24bba2","n":187,"o":"187-5","u":"Identifier une urgence","t":"Savoir reconnaître une anaphylaxie","q":"Quelles sont les manifestations systémiques graves d'une anaphylaxie (grade 2 ou plus) ?","a":"<p>Les manifestations systémiques graves (grade 2 ou plus) de l'anaphylaxie incluent :</p><ul><li>Un <strong>bronchospasme</strong>.</li><li>Une <strong>hypotension</strong>.</li><li>Un <strong>choc</strong>.</li><li>Des signes digestifs importants.</li></ul>"},{"i":"fc2ac4c99fa2","n":187,"o":"187-5","u":"Identifier une urgence","t":"Savoir reconnaître une anaphylaxie","q":"Quelle est la conduite à tenir immédiate lors de la reconnaissance d'une anaphylaxie ?","a":"<p>La conduite à tenir immédiate est l'administration d'<strong>adrénaline en intramusculaire</strong> (IM) sans délai.</p>"},{"i":"0be97a5ab7bb","n":187,"o":"187-7","u":"Prise en charge","t":"Connaître le traitement d'une urticaire aiguë","q":"Comment prend-on en charge une urticaire aiguë grave, notamment en présence d'un angio-œdème laryngé ou d'une anaphylaxie (grade > 2) ?","a":"<p>Le traitement repose sur l'<strong>adrénaline intramusculaire (IM)</strong> à la dose de <strong>0,01 mg/kg</strong>, sans dépasser <strong>0,5 mg</strong> par injection. Cette administration peut être répétée toutes les <strong>5 à 15 minutes</strong> si nécessaire. En cas de choc ou d'arrêt cardio-respiratoire, une administration intraveineuse (IV) titrée est indiquée.</p><p>Des mesures associées comprennent l'administration d'<strong>oxygène (8-9 L/min)</strong>, un <strong>remplissage vasculaire</strong> et des <strong>aérosols de β2-mimétiques</strong> si un asthme est également présent.</p>"},{"i":"2c02422cc0cc","n":187,"o":"187-7","u":"Prise en charge","t":"Connaître le traitement d'une urticaire aiguë","q":"Quelle est la première mesure à prendre en charge dans tous les cas d'urticaire aiguë quel que soit le contexte ?","a":"<p>La première mesure est l'<strong>éviction du facteur déclenchant</strong>.</p>"},{"i":"ba52eed94ec1","n":187,"o":"187-7","u":"Prise en charge","t":"Connaître le traitement d'une urticaire aiguë","q":"Quel est le traitement de première intention d'une urticaire aiguë non grave, sans atteinte muqueuse ?","a":"<p>Le traitement repose sur un <strong>anti-H1 de 2ème génération</strong> par voie orale, à raison de <strong>une fois par jour</strong>, pour une durée de <strong>1 à 2 semaines</strong>. Une forme injectable peut être envisagée en cas de poussée intense.</p>"},{"i":"33bb15a0220e","n":187,"o":"187-9","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la dermatite atopique en fonction du stade et son mode évolutif","q":"Quels sont les signes cliniques associés fréquemment à la dermatite atopique en dehors des lésions d'eczéma ?","a":"<p>Outre les lésions d'eczéma, la dermatite atopique est souvent associée à :</p><ul><li>Un <strong>prurit quasi-constant</strong>.</li><li>Une <strong>xérose cutanée</strong> (sécheresse de la peau).</li><li>Des <strong>dartres</strong> (macules hypopigmentées).</li><li>Le <strong>signe de Dennie-Morgan</strong> (double pli sous-palpébral).</li><li>Des <strong>fissures sous-auriculaires</strong>.</li></ul>"},{"i":"b8bd1762d11e","n":187,"o":"187-9","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la dermatite atopique en fonction du stade et son mode évolutif","q":"Comment se caractérisent les lésions cutanées de la dermatite atopique en phase aiguë chez le nourrisson ?","a":"<p>En phase aiguë, les lésions de dermatite atopique chez le nourrisson sont <strong>très prurigineuses</strong> et évoluent en plusieurs stades :</p><ul><li>Initialement <strong>érythémateuses</strong> (placards à contours émiettés, mal limités).</li><li>Puis <strong>vésiculeuses</strong>.</li><li>Ensuite <strong>suintantes</strong> avec des érosions.</li><li>Enfin <strong>croûteuses</strong>/desquamatives, guérissant sans cicatrice en <strong>7 à 15 jours</strong>.</li></ul>"},{"i":"bed8d86b27c8","n":187,"o":"187-9","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la dermatite atopique en fonction du stade et son mode évolutif","q":"Quelles sont les localisations typiques des lésions de dermatite atopique chez l'enfant et l'adolescent/adulte ?","a":"<ul><li>Chez l'<strong>enfant de plus de 2 ans</strong>, la dermatite atopique se localise préférentiellement au niveau des <strong>plis des coudes</strong> et des <strong>plis des genoux</strong>.</li><li>Chez l'<strong>adolescent et l'adulte</strong>, les lésions affectent principalement le <strong>visage</strong> et le <strong>cou</strong>.</li></ul>"},{"i":"eec34ad44e2a","n":187,"o":"187-9","u":"Diagnostic positif","t":"Connaître les aspects cliniques de la dermatite atopique en fonction du stade et son mode évolutif","q":"Quel est le mode évolutif classique de la dermatite atopique ?","a":"<p>La dermatite atopique évolue par <strong>poussées</strong>, souvent aggravées en <strong>hiver</strong>. Une amélioration est fréquente pendant l'enfance, bien que <strong>3 à 5 %</strong> des cas évoluent vers une forme adulte.</p>"}]};